'use strict';
let stageCategory='dungeon';
const STAGES_PER_PAGE=5,stagePages={dungeon:1,boss:1};
function stagePageItems(category,items){const start=(stagePages[category]-1)*STAGES_PER_PAGE;return items.slice(start,start+STAGES_PER_PAGE)}
function renderStagePagination(){const pager=$('stagePagination');pager.replaceChildren();const total=stageCategory==='dungeon'?STAGES.length:BOSS_STAGES.length;const pages=Math.max(5,Math.ceil(total/STAGES_PER_PAGE));for(let page=1;page<=pages;page++){const b=document.createElement('button');b.type='button';b.textContent=page;b.setAttribute('aria-label','หน้าด่าน '+page);if(page===stagePages[stageCategory])b.setAttribute('aria-current','page');b.onclick=()=>{stagePages[stageCategory]=page;renderStages()};pager.append(b)}const list=stageCategory==='dungeon'?$('stageList'):$('trialEntry');if(!list.children.length){const empty=document.createElement('p');empty.className='stage-page-empty';empty.textContent='ยังไม่มีด่านในหน้านี้';list.append(empty)}}
function updateCombatMeters(){const playing=player.map!=='town'&&!!run;$('combatMeter').hidden=true;$('eliteMeter').hidden=!playing||!!run?.trial||!!run?.tutorial;if(!playing)return;$('eliteFill').style.width=(run.eliteProgress||0)+'%';$('eliteCount').textContent=(run.eliteProgress||0)+' / 100'}
function selectStageCategory(category){stageCategory=category;for(const [id,key]of [['dungeonCategory','dungeon'],['bossCategory','boss']]){$(id).setAttribute('aria-selected',String(category===key));$(id).classList.toggle('selected',category===key)}$('stageList').hidden=category!=='dungeon';$('trialEntry').hidden=category!=='boss';renderStagePagination()}
window.addEventListener('DOMContentLoaded',()=>{$('dungeonCategory').onclick=()=>selectStageCategory('dungeon');$('bossCategory').onclick=()=>selectStageCategory('boss')});

let controlWindow=null;
const WINDOW_KEYS={KeyS:'skill',KeyD:'party',KeyF:'enchant'};
function openControlWindow(kind){if(screen!=='play'||run?.finished||(!$('modal').hidden&&!controlWindow))return;if(controlWindow===kind){closeModal();return}if(!$('characterOverlay').hidden)closeCharacterWindow();const titles={skill:'Skill',party:'Party',enchant:'Enchant'};if(!titles[kind])return;controlWindow=kind;const body=document.createElement('div');body.id='controlWindowBody';body.className='control-window-body';body.dataset.window=kind;body.setAttribute('aria-label',titles[kind]);modal(kind==='skill'?JOBS[player.job].name:titles[kind],body,kind==='skill'?[]:[['ปิด',closeModal,true]]);$('modal').classList.toggle('skill-modal',kind==='skill');if(kind==='skill'){selectedSwordSkill=null;renderSwordSkillWindow(body);$('modalCloseBtn').focus()}}
function handleWindowShortcut(e){if(screen!=='play'||run?.finished)return false;if(e.code==='KeyA'||e.code==='Tab'&&controlWindow){e.preventDefault();if(!e.repeat){closeModal();openCharacterWindow()}return true}const kind=WINDOW_KEYS[e.code];if(!kind||(!$('modal').hidden&&!controlWindow))return false;e.preventDefault();if(!e.repeat)openControlWindow(kind);return true}
window.addEventListener('DOMContentLoaded',()=>{for(const [id,kind]of [['skillMenuBtn','skill'],['partyMenuBtn','party'],['enchantMenuBtn','enchant']])$(id).onclick=()=>openControlWindow(kind)});
